#!/bin/bash
# usage: ui.sh tap <id> | shot <name> | ids | swipe x1 y1 x2 y2 | type text
S=/private/tmp/claude-501/-Users-itome-shopbench-runs-nativephp/62ece232-cdb0-4f52-9127-7032ed7f939b/scratchpad
UDID=${UDID:-$(cat $S/udid)}
AXE=$S/axe/axe
case "$1" in
  tap) $AXE tap --id "$2" --udid $UDID ;;
  shot) xcrun simctl io $UDID screenshot $S/$2.png >/dev/null 2>&1; sips -Z 800 $S/$2.png --out $S/$2.png >/dev/null; echo $S/$2.png ;;
  ids) $AXE describe-ui --udid $UDID | python3 -c "
import json,sys
d=json.load(sys.stdin)
def walk(n):
    i=n.get('AXUniqueId')
    if i: print(n.get('type'), i, repr(n.get('AXLabel'))[:50], {k:round(v) for k,v in n.get('frame',{}).items()})
    for c in n.get('children',[]): walk(c)
for n in (d if isinstance(d,list) else [d]): walk(n)
" ;;
  swipe) $AXE swipe --start-x $2 --start-y $3 --end-x $4 --end-y $5 --udid $UDID ;;
  type) $AXE type "$2" --udid $UDID ;;
esac
EOF
